import { execFileSync, spawn } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync, } from "node:fs";
import { createServer } from "node:http";
import { tmpdir } from "node:os";
import path from "node:path";
import { inflateSync } from "node:zlib";
import { buildSync } from "esbuild";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import cases from "./runnerCases.json" with { type: "json" };
const ID = "11111111-1111-4111-8111-111111111111";
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const FAKE_REPLAY = `for last; do :; done
if [ "$last" = "--print-api-key" ]; then
  printf '@@bitfab:api-key {"apiKey":"bf_local","serviceUrl":"%s"}\\n' "$BITFAB_TEST_SERVICE"
  exit 0
fi
mark="$BITFAB_TEST_MARK"
printf '%s\\n' "$@" > "$mark/args"
pwd -P > "$mark/cwd"
env > "$mark/env"
git symbolic-ref --short -q HEAD > "$mark/branch" 2>/dev/null
if [ -n "$BITFAB_CODE_CHANGE_PATH" ]; then cp "$BITFAB_CODE_CHANGE_PATH" "$mark/change.json"; fi
cat "$mark/out"
cat "$mark/err" >&2
exit "$(cat "$mark/code")"
`;
const DEFAULT_RESPONSES = {
    "GET /token": { status: 200, body: { value: "oidc-token" } },
    "POST /api/sdk/replay/cloudKey/redeem": {
        status: 200,
        body: { apiKey: "bf_temporary" },
    },
    "DELETE /api/sdk/replay/cloudKey": { status: 200, body: {} },
};
let scratch;
let helper;
async function startApi(responses) {
    const requests = [];
    const answers = { ...DEFAULT_RESPONSES, ...responses };
    const server = createServer((request, response) => {
        let body = "";
        request.on("data", (chunk) => {
            body += chunk;
        });
        request.on("end", () => {
            const url = new URL(request.url ?? "/", "http://localhost");
            requests.push({
                method: request.method,
                path: url.pathname,
                query: url.search.slice(1),
                authorization: request.headers.authorization ?? null,
                body: body === "" ? undefined : JSON.parse(body),
            });
            const answer = answers[`${request.method} ${url.pathname}`] ?? {
                status: 404,
                body: {},
            };
            response.writeHead(answer.status, {
                "Content-Type": "application/json",
                ...(answer.location ? { Location: answer.location } : {}),
            });
            response.end(answer.raw ?? JSON.stringify(answer.body));
        });
    });
    await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
    const { port } = server.address();
    return { server, url: `http://127.0.0.1:${port}`, requests };
}
function run(args, cwd, env) {
    return new Promise((resolve) => {
        const child = spawn(process.execPath, args, { cwd, env });
        let stdout = "";
        let stderr = "";
        child.stdout.on("data", (chunk) => {
            stdout += chunk;
        });
        child.stderr.on("data", (chunk) => {
            stderr += chunk;
        });
        child.on("close", (code) => resolve({ code, stdout, stderr }));
    });
}
function git(cwd, ...args) {
    return execFileSync("git", ["-c", "user.name=test", "-c", "user.email=test@example.com", ...args], {
        cwd,
        encoding: "utf8",
        env: { ...process.env, GIT_CONFIG_NOSYSTEM: "1" },
    }).trim();
}
function writeFiles(root, files = {}) {
    for (const [file, content] of Object.entries(files)) {
        mkdirSync(path.dirname(path.join(root, file)), { recursive: true });
        writeFileSync(path.join(root, file), content);
    }
}
function setUp(testCase, directory) {
    const root = path.join(directory, "repo");
    const mark = path.join(directory, "mark");
    mkdirSync(root);
    mkdirSync(mark);
    git(root, "init", "-q", "-b", "main");
    writeFiles(root, testCase.files);
    git(root, "add", "-A");
    git(root, "commit", "-q", "--allow-empty", "-m", "Initial commit");
    const base = git(root, "rev-parse", "HEAD");
    const env = {};
    if (testCase.snapshot) {
        const request = JSON.parse(JSON.stringify(testCase.snapshot.request).replaceAll('"BASE"', `"${base}"`));
        request.id ??= ID;
        git(root, "checkout", "-q", "-b", `bitfab-replay/${request.id}`);
        writeFiles(root, testCase.snapshot.files);
        for (const file of testCase.snapshot.remove ?? []) {
            rmSync(path.join(root, file));
        }
        git(root, "add", "-A");
        git(root, "commit", "-q", "--allow-empty", "-m", `Bitfab replay snapshot\n\n${JSON.stringify(request)}`);
        env.GITHUB_REF_NAME = testCase.snapshot.ref ?? `bitfab-replay/${request.id}`;
    }
    else {
        if (testCase.origin) {
            const origin = path.join(directory, "origin.git");
            execFileSync("git", ["init", "-q", "--bare", "-b", "main", origin]);
            git(root, "remote", "add", "origin", origin);
            git(root, "push", "-q", "origin", "main");
        }
        git(root, "checkout", "-q", "-b", "dev");
        if (testCase.branchFiles) {
            writeFiles(root, testCase.branchFiles);
            git(root, "add", "-A");
            git(root, "commit", "-q", "-m", "Change on dev");
        }
        const inputs = { ...testCase.inputs };
        if (inputs.request !== undefined) {
            inputs.request = JSON.stringify(inputs.request);
        }
        if (inputs.requestText !== undefined) {
            inputs.request = inputs.requestText;
            delete inputs.requestText;
        }
        if (inputs.requestBase64 !== undefined) {
            inputs.request = Buffer.from(JSON.stringify(inputs.requestBase64)).toString("base64");
            delete inputs.requestBase64;
        }
        const event = path.join(directory, "event.json");
        writeFileSync(event, JSON.stringify({ ...testCase.event, inputs }));
        env.GITHUB_REF_NAME = "dev";
        env.GITHUB_EVENT_PATH = event;
    }
    const replay = testCase.replay ?? {};
    writeFileSync(path.join(mark, "out"), replay.stdout ?? "");
    writeFileSync(path.join(mark, "err"), replay.stderr ?? "");
    writeFileSync(path.join(mark, "code"), String(replay.exitCode ?? 0));
    const script = path.join(directory, "replay.sh");
    writeFileSync(script, FAKE_REPLAY);
    const sha = git(root, "rev-parse", "HEAD");
    Object.assign(env, {
        PATH: process.env.PATH ?? "",
        HOME: directory,
        GIT_CONFIG_NOSYSTEM: "1",
        GITHUB_RUN_ATTEMPT: "1",
        GITHUB_SHA: sha,
        GITHUB_WORKFLOW_REF: "acme/app/.github/workflows/bitfab-replay.yml@refs/heads/dev",
        GITHUB_STEP_SUMMARY: path.join(directory, "summary.md"),
        RUNNER_TEMP: directory,
        BITFAB_REPLAY_COMMAND: JSON.stringify(["sh", script]),
        BITFAB_API_KEY: "test",
        BITFAB_TEST_MARK: mark,
        ...testCase.env,
    });
    return { root, mark, env };
}
function decodeResult(stdout) {
    const encoded = stdout
        .split("\n")
        .filter((line) => line.startsWith("bitfab-replay-result "))
        .map((line) => line.slice("bitfab-replay-result ".length))
        .join("");
    if (encoded === "") {
        return null;
    }
    return JSON.parse(inflateSync(Buffer.from(encoded, "base64")).toString("utf8"));
}
function replayed(root, mark) {
    if (!existsSync(path.join(mark, "args"))) {
        return false;
    }
    const env = {};
    for (const line of readFileSync(path.join(mark, "env"), "utf8").split("\n")) {
        const match = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/.exec(line);
        if (match) {
            env[match[1]] = match[2];
        }
    }
    const cwd = path.relative(realpathSync(root), readFileSync(path.join(mark, "cwd"), "utf8").trim());
    const change = path.join(mark, "change.json");
    return {
        args: readFileSync(path.join(mark, "args"), "utf8")
            .split("\n")
            .slice(0, -1),
        cwd: cwd === "" ? "." : cwd,
        env,
        branch: readFileSync(path.join(mark, "branch"), "utf8").trim(),
        codeChange: existsSync(change)
            ? JSON.parse(readFileSync(change, "utf8"))
            : null,
    };
}
function checkCase(testCase, run) {
    const { expect: expected } = testCase;
    const context = testCase.name;
    expect(run.code, `${context}\n${run.stdout}\n${run.stderr}`).toBe(expected.exitCode);
    for (const text of expected.stdout ?? []) {
        expect(run.stdout, context).toContain(text);
    }
    for (const text of expected.notStdout ?? []) {
        expect(run.stdout, context).not.toContain(text);
    }
    for (const text of expected.stderr ?? []) {
        expect(run.stderr, context).toContain(text);
    }
    if (run.result !== null) {
        expect(UUID_PATTERN.test(run.result.executionId), context).toBe(true);
        expect(run.result.commitSha, context).toBe(run.env.GITHUB_SHA);
    }
    if (expected.result) {
        expect(run.result, context).toMatchObject(expected.result);
    }
    if (expected.resultStdoutJson) {
        expect(JSON.parse(run.result.stdout), context).toEqual(expected.resultStdoutJson);
    }
    if (expected.requests) {
        expect(run.requests, context).toHaveLength(expected.requests.length);
        for (const [index, wanted] of expected.requests.entries()) {
            expect(run.requests[index], `${context}: request ${index}`).toMatchObject(wanted);
        }
    }
    for (const text of expected.summary ?? []) {
        expect(run.summary, context).toContain(text);
    }
    if (expected.replayed === false) {
        expect(run.replayed, context).toBe(false);
    }
    else if (expected.replayed) {
        const { env, ...rest } = expected.replayed;
        expect(run.replayed, context).toMatchObject(rest);
        for (const [name, value] of Object.entries(env ?? {})) {
            expect(run.replayed.env[name], `${context}: ${name}`).toBe(value ?? undefined);
        }
    }
}
describe("shared runner cases", () => {
    beforeAll(() => {
        scratch = mkdtempSync(path.join(tmpdir(), "bitfab-runner-cases-"));
        helper = path.join(scratch, "cloudReplay.mjs");
        const built = buildSync({
            entryPoints: [path.join(import.meta.dirname, "bin.ts")],
            bundle: true,
            platform: "node",
            format: "esm",
            target: "node18",
            write: false,
            banner: {
                js: 'import { createRequire } from "node:module"; const require = createRequire(import.meta.url);',
            },
        });
        writeFileSync(helper, built.outputFiles[0].text);
    });
    afterAll(() => {
        rmSync(scratch, { recursive: true, force: true });
    });
    for (const [index, testCase] of cases.cases.entries()) {
        it(testCase.name, async () => {
            const directory = realpathSync(mkdtempSync(path.join(scratch, `case-${index}-`)));
            const { root, mark, env } = setUp(testCase, directory);
            const api = testCase.api ? await startApi(testCase.api) : null;
            if (api !== null) {
                env.BITFAB_TEST_SERVICE = api.url;
                env.ACTIONS_ID_TOKEN_REQUEST_URL = `${api.url}/token`;
                env.ACTIONS_ID_TOKEN_REQUEST_TOKEN = "bearer-test";
            }
            const child = await run([helper, "--cloud-execute"], root, env).finally(() => api?.server.close());
            const summaryPath = env.GITHUB_STEP_SUMMARY;
            checkCase(testCase, {
                requests: api?.requests ?? [],
                code: child.code,
                stdout: child.stdout,
                stderr: child.stderr,
                env,
                result: decodeResult(child.stdout),
                summary: existsSync(summaryPath)
                    ? readFileSync(summaryPath, "utf8")
                    : "",
                replayed: replayed(root, mark),
            });
        });
    }
});
